// health-dashboard — сборка JSON для вкладки «Здоровье». Пишет в Static Data.
// Источники (по имени ноды): Get Daily_Trends, Get Anomalies_Log, Get Correlations_Log,
// Get Recommendations_Log, Get Doctor_Notes. Все — книга Health_DB. Run Once for All Items.
// Контракт намеренно «сырой/семантический» (не форматированные строки) — вёрстка ещё меняется.

function safeAll(name) { try { return $(name).all().map(i => i.json); } catch (e) { return []; } }
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace('%', '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function dkey(v) { return String(v == null ? '' : v).slice(0, 10); }
// Doctor_Notes хранит дату как YYYY.MM.DD (точки) — dkey() тут даёт мусор при
// сравнении с ISO-датами Daily_Trends. Нормализуем отдельно, как в advisor/phenoage.
function d10(v) {
  let s = String(v == null ? '' : v).trim();
  let m = s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  m = s.match(/^(\d{4})[.\/-](\d{1,2})[.\/-](\d{1,2})/);
  if (m) return m[1] + '-' + m[2].padStart(2, '0') + '-' + m[3].padStart(2, '0');
  return s.slice(0, 10);
}
function avg(a) { const x = a.filter(v => v != null); return x.length ? x.reduce((s, v) => s + v, 0) / x.length : null; }
function r1(x) { return x == null ? null : Math.round(x * 10) / 10; }
// Округление по величине: шаги/минуты не нужны с десятыми, ВСР/эффективность — нужны.
function rSmart(x) {
  if (x == null) return null;
  return Math.abs(x) >= 100 ? Math.round(x) : Math.round(x * 10) / 10;
}

const daily = safeAll('Get Daily_Trends');
const anom = safeAll('Get Anomalies_Log');
const corr = safeAll('Get Correlations_Log');
const recs = safeAll('Get Recommendations_Log');
const notes = safeAll('Get Doctor_Notes');

// колонки Daily_Trends -> ключи фронта
const COL = {
  hrv: 'ВСР_ночная',
  rhr: 'Пульс_ночной_средний',
  body_battery: 'Восстановление_BodyBattery',
  sleep_score: 'Оценка_сна_балл',
  sleep_min: 'Чистый_сон_мин',
  stress: 'Стресс_дневной_средний',
  steps: 'Шаги_за_вчера',
  sleep_eff: 'Эффективность_сна_',
  vo2max: 'VO2_Max',
  respiration: 'Дыхание_ночь_среднее',
  spo2: 'SpO2_ночь_среднее',
};

// Целевые зоны — популяционные ориентиры для графиков (не личная база).
// null = зоны нет, ориентир только личная база.
const TARGET_ZONES = {
  sleep_min:   { min: 420, max: 540, label: '7–9 ч' },
  sleep_eff:   { min: 85,  max: 100, label: '85–100%' },
  spo2:        { min: 95,  max: 100, label: '95–100%' },
  respiration: { min: 12,  max: 20,  label: '12–20/мин' },
};

// ---------------------------------------------------------------------------
// КОНФИГ МЕТРИК — зеркало конфига воркфлоу `Anomaly_Detector/Correlations`
// (нода "Anomaly Detection"). direction и minAbsDelta ДОЛЖНЫ совпадать с ним:
// это единственный источник правды «что считать хорошим» и «что считать шумом».
// При правке там — поправить и здесь.
// ---------------------------------------------------------------------------
const METRICS = [
  { key: 'rhr',          col: 'Пульс_ночной_средний',       label: 'Пульс покоя',    unit: 'уд/мин', direction: 'lower_better',  minAbsDelta: 3 },
  { key: 'hrv',          col: 'ВСР_ночная',                 label: 'ВСР ночью',      unit: 'мс',     direction: 'higher_better', minAbsDelta: 6 },
  { key: 'body_battery', col: 'Восстановление_BodyBattery', label: 'Body Battery',   unit: '',       direction: 'higher_better', minAbsDelta: 12 },
  { key: 'sleep_min',    col: 'Чистый_сон_мин',             label: 'Чистый сон',     unit: 'мин',    direction: 'higher_better', minAbsDelta: 30 },
  { key: 'sleep_score',  col: 'Оценка_сна_балл',            label: 'Оценка сна',     unit: 'балл',   direction: 'higher_better', minAbsDelta: 7 },
  { key: 'sleep_eff',    col: 'Эффективность_сна_',         label: 'Эффективность сна', unit: '%',   direction: 'higher_better', minAbsDelta: 4 },
  { key: 'stress',       col: 'Стресс_дневной_средний',     label: 'Стресс дневной', unit: '',       direction: 'lower_better',  minAbsDelta: 6 },
  { key: 'steps',        col: 'Шаги_за_вчера',              label: 'Шаги',           unit: '',       direction: 'neutral',       minAbsDelta: 3500 },
  { key: 'vo2max',       col: 'VO2_Max',                    label: 'VO2 Max',        unit: '',       direction: 'higher_better', minAbsDelta: 2 },
];

// Метрики без личной базы — оцениваются по популяционному референсу, а не по «своей норме».
const REFERENCE_METRICS = [
  { key: 'respiration', col: 'Дыхание_ночь_среднее', label: 'Дыхание ночью', unit: '/мин', ref_min: 12, ref_max: 20 },
  { key: 'spo2',        col: 'SpO2_ночь_среднее',    label: 'SpO2 ночью',    unit: '%',    ref_min: 95, ref_max: 100 },
];

const BASE_WINDOWS = [ { days: 30, minPoints: 10 }, { days: 7, minPoints: 4 } ];

// Базовая линия = среднее по окну ДО текущего дня (как в детекторе аномалий).
function baselineFor(sortedRows, col, uptoIdx, windowDays, minPoints) {
  const cur = new Date(dkey(sortedRows[uptoIdx]['Дата']) + 'T00:00:00Z');
  const from = new Date(cur); from.setUTCDate(from.getUTCDate() - windowDays);
  const vals = [];
  for (let i = 0; i < uptoIdx; i++) {
    const d = new Date(dkey(sortedRows[i]['Дата']) + 'T00:00:00Z');
    if (d >= from && d < cur) {
      const v = num(sortedRows[i][col]);
      if (v != null) vals.push(v);
    }
  }
  if (vals.length < minPoints) return null;
  const m = vals.reduce((s, v) => s + v, 0) / vals.length;
  const sd = vals.length > 1
    ? Math.sqrt(vals.reduce((s, v) => s + (v - m) ** 2, 0) / (vals.length - 1))
    : null;
  return { mean: m, std: sd, n: vals.length, days: windowDays };
}

// judgment считает БЭКЕНД, фронтенд только отображает.
// Отклонение меньше minAbsDelta = шум, а не сигнал.
function judge(direction, deltaAbs, minAbsDelta) {
  if (direction === 'neutral') return 'neutral';
  if (deltaAbs == null || Math.abs(deltaAbs) < minAbsDelta) return 'neutral';
  const better = direction === 'higher_better' ? deltaAbs > 0 : deltaAbs < 0;
  return better ? 'good' : 'bad';
}

const rows = daily
  .filter(r => r['Дата'])
  .sort((a, b) => dkey(a['Дата']).localeCompare(dkey(b['Дата'])));
const lastRow = rows[rows.length - 1] || {};
const lastDate = dkey(lastRow['Дата']) || dkey(new Date().toISOString());

// --- сегодня: сырая последняя строка + распарсенные ключевые метрики ---
const todayParsed = {};
for (const k of Object.keys(COL)) todayParsed[k] = num(lastRow[COL[k]]);
const rawToday = {};
for (const [key, val] of Object.entries(lastRow)) {
  if (key === 'row_number') continue;
  rawToday[key] = val;
}

// --- метрики с личной базой (Фаза 1): value + baseline + delta + judgment ---
const lastIdx = rows.length - 1;
const metrics = [];
for (const m of METRICS) {
  const value = num(lastRow[m.col]);
  let base = null;
  if (lastIdx > 0) {
    for (const w of BASE_WINDOWS) {
      base = baselineFor(rows, m.col, lastIdx, w.days, w.minPoints);
      if (base) break;
    }
  }
  const deltaAbs = (value != null && base) ? value - base.mean : null;
  const deltaPct = (deltaAbs != null && base.mean) ? (deltaAbs / base.mean) * 100 : null;
  metrics.push({
    key: m.key, label: m.label, unit: m.unit,
    value: value != null ? rSmart(value) : null,
    baseline: base ? rSmart(base.mean) : null,
    baseline_days: base ? base.days : null,
    baseline_n: base ? base.n : null,
    delta_abs: deltaAbs != null ? rSmart(deltaAbs) : null,
    delta_pct: deltaPct != null ? Math.round(deltaPct) : null,
    z: (value != null && base && base.std) ? Math.round(((value - base.mean) / base.std) * 100) / 100 : null,
    direction: m.direction,
    judgment: judge(m.direction, deltaAbs, m.minAbsDelta),
    kind: 'baseline',
  });
}
// метрики без личной базы — по популяционному референсу
for (const m of REFERENCE_METRICS) {
  const value = num(lastRow[m.col]);
  let judgment = 'neutral';
  if (value != null) judgment = (value >= m.ref_min && value <= m.ref_max) ? 'good' : 'bad';
  metrics.push({
    key: m.key, label: m.label, unit: m.unit,
    value: value != null ? r1(value) : null,
    ref_min: m.ref_min, ref_max: m.ref_max,
    baseline: null, delta_abs: null, delta_pct: null,
    direction: 'reference', judgment, kind: 'reference',
  });
}

// --- последние 14 дней (точки для графиков) ---
// Каждый день получает и значение, и оценку <key>_j относительно текущей личной базы,
// по тем же direction/minAbsDelta. Фронтенд не считает «хорошо/плохо» сам.
const metricByKey = {};
metrics.forEach(m => { metricByKey[m.key] = m; });
const cfgByKey = {};
METRICS.forEach(m => { cfgByKey[m.key] = m; });

const last14 = rows.slice(-14).map(r => {
  const o = { date: dkey(r['Дата']) };
  for (const k of Object.keys(COL)) {
    const v = num(r[COL[k]]);
    o[k] = v;
    const cfg = cfgByKey[k];
    const met = metricByKey[k];
    if (cfg && met && met.baseline != null && v != null) {
      o[k + '_j'] = judge(cfg.direction, v - met.baseline, cfg.minAbsDelta);
    } else if (TARGET_ZONES[k] && v != null) {
      const z = TARGET_ZONES[k];
      o[k + '_j'] = (v >= z.min && v <= z.max) ? 'good' : 'bad';
    } else {
      o[k + '_j'] = 'neutral';
    }
  }
  return o;
});

// --- тренды: эта неделя vs прошлая (7+7) ---
const wk = rows.slice(-7), pw = rows.slice(-14, -7);
function trend(k) {
  const a = avg(wk.map(r => num(r[COL[k]])));
  const b = avg(pw.map(r => num(r[COL[k]])));
  const delta_pct = (a != null && b != null && b !== 0) ? Math.round(((a - b) / b) * 100) : null;
  const delta_abs = (a != null && b != null) ? a - b : null;
  // направление и порог шума берём из того же конфига METRICS — второй логики «хорошо/плохо» нет
  const cfg = METRICS.find(m => m.key === k);
  const direction = cfg ? cfg.direction : 'neutral';
  const judgment = cfg ? judge(direction, delta_abs, cfg.minAbsDelta) : 'neutral';
  return { this_week: rSmart(a), prev_week: rSmart(b), delta_abs: rSmart(delta_abs), delta_pct, direction, judgment };
}
const trends = {};
for (const k of Object.keys(COL)) trends[k] = trend(k);

// --- аномалии: самая свежая запись + история метрики за 14 дней ---
const anomSorted = [...anom].sort((a, b) => dkey(b.date).localeCompare(dkey(a.date)));
const latestAnom = anomSorted[0];
let anomalies = { report_date: null, count: 0, strong_count: 0, items: [] };
if (latestAnom) {
  let raw = [];
  try { raw = JSON.parse(latestAnom.raw_anomalies || '[]'); } catch (e) {}
  const hist14 = rows.slice(-14);
  anomalies = {
    report_date: dkey(latestAnom.date) || null,
    count: Number(latestAnom.anomaly_count) || raw.length,
    strong_count: Number(latestAnom.strong_count) || 0,
    items: raw.map(a => ({
      metric: a.metric || null,
      label: a.label || a.metric || null,
      direction: a.direction || null,
      severity: a.severity || null,
      interpretation: a.interpretation || null,
      baseline_mean: num(a.baseline_mean),
      history: hist14.map(r => num(r[a.metric])).filter(v => v != null),
    })),
  };
}

// --- корреляции: последний расчёт ---
let correlations = { computed: null, priority: [], discovery: [] };
if (corr.length) {
  const maxC = corr.map(r => dkey(r.date_computed)).sort().slice(-1)[0];
  const latest = corr.filter(r => dkey(r.date_computed) === maxC);
  correlations.computed = maxC;
  for (const r of latest) {
    const item = { a: r.metric_a, b: r.metric_b, lag: num(r.lag_days), r: num(r.r), n: num(r.n), p_adj: num(r.p_adj) };
    if (String(r.type || '').includes('priority')) {
      if (item.r != null && Math.abs(item.r) >= 0.2) correlations.priority.push(item);
    } else {
      correlations.discovery.push(item);
    }
  }
  correlations.discovery = correlations.discovery
    .sort((a, b) => Math.abs(b.r || 0) - Math.abs(a.r || 0)).slice(0, 12);
}

// --- последняя рекомендация советника ---
const recSorted = [...recs]
  .filter(r => r.Recommendation_Text && dkey(r.Date) <= lastDate)
  .sort((a, b) => dkey(b.Date).localeCompare(dkey(a.Date)));
const recParsedLatest = recSorted[0] ? parseActions(recSorted[0].Recommendation_Text) : null;
const recommendation = recSorted[0] ? {
  date: dkey(recSorted[0].Date),
  period_type: recSorted[0].Period_Type || null,
  text: stripActions(recSorted[0].Recommendation_Text),
  actions: recParsedLatest ? recParsedLatest.actions : [],
} : null;

// --- Фаза 5: гипотезы-эксперименты из Correlations_Log ---
// Человеческие подписи колонок Daily_Trends для читаемых формулировок.
const COL_LABEL = {
  'Чистый_сон_мин':'чистый сон', 'Эффективность_сна_':'эффективность сна', 'Оценка_сна_балл':'оценка сна',
  'Пульс_ночной_средний':'пульс покоя', 'ВСР_ночная':'ВСР', 'Восстановление_BodyBattery':'Body Battery',
  'Стресс_дневной_средний':'дневной стресс', 'Шаги_за_вчера':'шаги', 'VO2_Max':'VO2 Max',
  'Питание_Всего_Ккал':'калории', 'Питание_Всего_Белки_г':'белок', 'Питание_Всего_Жиры_г':'жиры',
  'Питание_Всего_Углеводы_г':'углеводы', 'Алкоголь_гр':'алкоголь', 'Время_последнего_кофе':'время последнего кофе',
  'Экранное_время_всего_ч':'экранное время', 'Экран_перед_сном_мин':'экран перед сном',
  'Тренировка_Ккал':'нагрузка', 'Окно_голода_до_сна_ч':'окно голода до сна',
  'Длительность_голода_ч':'длительность голода', 'Температура_avg_C':'температура',
  'Атмосферное_давление_ночь_hPa':'атм. давление', 'Пробуждения_кол_во':'пробуждения',
};
function colLabel(c) {
  if (!c) return '';
  return COL_LABEL[c] || String(c).replace(/_/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
}

// Не всякая сильная корреляция — инсайт. Отсекаем два класса мусора:
//  1) тавтологии внутри архитектуры сна (эффективность сна СЧИТАЕТСЯ из бодрствования);
//  2) «нутриент ↔ нутриент» — это просто состав еды, а не поведение → результат.
// Интересна только связка «то, чем я управляю» × «физиология/сон».
const FAM_SLEEP = new Set(['Чистый_сон_мин','REM_сон_мин','Легкий_сон_мин','Бодрствование_мин',
  'Эффективность_сна_','Оценка_сна_балл','Время_в_кровати_мин','Пробуждения_кол_во','Глубокий_сон_мин']);
const FAM_INTAKE = new Set(['Кофеин','Добавленный сахар','Клетчатка','Железо','Калий','Магний','Цинк',
  'Витамин B12','Витамин D','Витамин Е','Омега-3 (EPA/DHA)','Ужин_Жиры_г','Алкоголь_гр',
  'Питание_Всего_Ккал','Питание_Всего_Белки_г','Питание_Всего_Жиры_г','Питание_Всего_Углеводы_г']);
const FAM_ACT = new Set(['Тренировка_Ккал','Шаги_за_вчера','Экранное_время_всего_ч','Экран_перед_сном_мин']);
const FAM_PHYS = new Set(['ВСР_ночная','Восстановление_BodyBattery','Пульс_ночной_средний',
  'Стресс_дневной_средний','VO2_Max']);
function famOf(c) {
  if (FAM_SLEEP.has(c)) return 'sleep';
  if (FAM_INTAKE.has(c)) return 'intake';
  if (FAM_ACT.has(c)) return 'activity';
  if (FAM_PHYS.has(c)) return 'physio';
  return 'other';
}
function isActionablePair(a, b) {
  const fa = famOf(a), fb = famOf(b);
  if (fa === fb) return false;                       // одна семья — тавтология или состав еды
  const lever = ['intake','activity'];
  const outcome = ['sleep','physio'];
  return (lever.includes(fa) && outcome.includes(fb)) || (lever.includes(fb) && outcome.includes(fa));
}

const experiments = [];
if (corr.length) {
  const maxC2 = corr.map(r => dkey(r.date_computed)).sort().slice(-1)[0];
  const seenPair = new Set();
  corr.filter(r => dkey(r.date_computed) === maxC2)
    .map(r => ({
      a: r.metric_a, b: r.metric_b, r: num(r.r), n: num(r.n),
      p: num(r.p_adj), lag: num(r.lag_days), type: String(r.type || ''),
    }))
    .filter(x => x.r != null && x.n != null && x.n >= 30 && Math.abs(x.r) >= 0.25)
    .filter(x => isActionablePair(x.a, x.b))
    .sort((x, y) => Math.abs(y.r) - Math.abs(x.r))
    .forEach(x => {
      const key = [x.a, x.b].sort().join('|');
      if (seenPair.has(key)) return;
      seenPair.add(key);
      if (experiments.length >= 2) return;
      // рычаг всегда ставим в начало формулировки: «больше X → Y выше/ниже»
      const leverIsA = ['intake','activity'].includes(famOf(x.a));
      const lever = leverIsA ? x.a : x.b;
      const outcome = leverIsA ? x.b : x.a;
      const solid = (x.p != null && x.p < 0.05) && x.n >= 21;
      experiments.push({
        hypothesis: 'больше «' + colLabel(lever) + '» → ' + colLabel(outcome) + (x.r > 0 ? ' выше' : ' ниже'),
        lever: colLabel(lever), outcome: colLabel(outcome),
        r: Math.round(x.r * 100) / 100, n: x.n,
        p_adj: x.p != null ? Math.round(x.p * 1000) / 1000 : null,
        lag_days: x.lag,
        strength: Math.abs(x.r) >= 0.6 ? 'сильная' : Math.abs(x.r) >= 0.45 ? 'заметная' : 'слабая',
        status: solid ? 'supported' : 'candidate',
        confidence: solid
          ? 'подтверждается статистикой (p<0.05)'
          : 'НЕ подтверждено статистикой — пока только кандидат, нужно больше данных',
        priority: x.type.includes('priority'),
      });
    });
}

// --- Фаза 3/4: структурные действия советника и замкнутые циклы ---
// Блок <<<ACTIONS {...} ACTIONS>>> дописывается советником в конец Recommendation_Text.
function parseActions(txt) {
  const m = String(txt || '').match(/<<<ACTIONS\s*([\s\S]*?)\s*ACTIONS>>>/);
  if (!m) return null;
  try {
    const o = JSON.parse(m[1].trim());
    if (!o || !Array.isArray(o.actions)) return null;
    return o;
  } catch (e) { return null; }
}
function stripActions(txt) {
  return String(txt || '').replace(/<<<ACTIONS[\s\S]*?ACTIONS>>>/, '').trim();
}
// среднее метрики за окно [from, to] включительно
function meanBetween(col, fromISO, toISO) {
  const vals = [];
  for (const r of rows) {
    const d = dkey(r['Дата']);
    if (d >= fromISO && d <= toISO) {
      const v = num(r[col]);
      if (v != null) vals.push(v);
    }
  }
  return vals.length ? { mean: vals.reduce((s, v) => s + v, 0) / vals.length, n: vals.length } : null;
}
function shiftDays(iso, n) {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

const recsWithActions = [...recs]
  .filter(r => r.Recommendation_Text && d10(r.Date))
  .map(r => ({ date: d10(r.Date), parsed: parseActions(r.Recommendation_Text) }))
  .filter(r => r.parsed && r.parsed.actions.length)
  .sort((a, b) => b.date.localeCompare(a.date));

// Замкнутые циклы: для советов, с момента которых прошло >= 7 дней,
// сравниваем 7 дней ДО выдачи и 7 дней ПОСЛЕ по метрике действия.
const action_loops = [];
for (const rec of recsWithActions) {
