  window: { from: last14[0] ? last14[0].date : null, to: lastDate },
  today: { date: lastDate, parsed: todayParsed, raw: rawToday },
  metrics,          // Фаза 1: значение + личная база + judgment (считает бэкенд)
  target_zones: TARGET_ZONES,   // Фаза 2: популяционные зоны для графиков
  days_14: last14,  // бывш. `week` — тут 14 дней, а не 7
  trends,
  anomalies,
  correlations,
  recommendation,
  action_loops,     // Фаза 4: советы, у которых уже можно измерить результат
  experiments,      // Фаза 5: гипотезы «рычаг → результат» (мусорные пары отсеяны)
  experiments_note: experiments.length ? null : 'Действенных связей «поведение → результат» пока не найдено: все сильные корреляции в данных — это либо состав еды (нутриент ↔ нутриент), либо внутренняя арифметика сна.',
  medical_notes_recent,
};

